  const tiers = p.tiers || [];
  if (!tiers.length || !p.raised) return;
  const priced = tiers.map((t, i) => ({ t, i, usd: t.priceUSD || 0, cap: t.count != null ? t.count : t.supply || 0 })).filter((x) => x.usd > 0).sort((a, b) => b.usd - a.usd);
