  if (left !== 0) {
    cheapest.t.sold = Math.max(0, Math.min(cheapest.cap, cheapest.t.sold + Math.round(left / cheapest.usd)));
  }
  p.raised = tiers.reduce((a, t) => a + (t.sold || 0) * (t.priceUSD || 0), 0);
